INSERT 
  INTO 
  		RECIPES 
  		(
    	MEMBER_NO
     ,  RECIPE_TITLE
     ,  RECIPE_INFO
     ,  RECIPE_MAIN_IMG
     ,  RECIPES_IMG_PATH
        ) 
VALUES 
		(
    	#{memberNo}
     ,  #{recipeTitle}
     ,  #{recipeInfo}
     ,  #{recipeMainImg}
     ,  #{recipesImgPath}
     	)

        INSERT
          INTO 
             	MATERIAL 
             	(
				RECIPE_NO
			 ,  MATERIAL_NAME
			 ,  AMOUNT
			    ) 
	    VALUES 
	        	(
				#{recipeNo}
			 ,  #{materialName}
			 ,  #{amount}
			    )

        INSERT
          INTO
             	RECIPE_STEPS
             	(
				RECIPE_NO
			 ,  STEP_INFO
			 ,  STEP_IMG
			 ,  STEP_ORDER
			 ,  STEP_IMG_PATH
			    )
	    VALUES
	        	(
				#{recipeNo}
			 ,  #{stepInfo}
			 ,  #{stepImg}
			 ,  #{stepOrder}
			 ,  #{stepImgPath}
			    )
